"""L5 -- who is it worse for.

You now have a working detector and something built on top of it. The question
this level asks is the one that matters when it ships: does it work equally
well for everyone it will be pointed at?

`provided/faces.csv` records, for each image, a `group` and the ground-truth
box. Read `provided/PROVENANCE.md` before you interpret anything you compute
here -- particularly the part about which gap this data can honestly show and
which one it cannot. The memo is graded partly on getting that distinction
right, and a confident claim this corpus does not support will cost you more
than an honest limitation.
"""

from __future__ import annotations

from pathlib import Path



def detection_rate_by_group(detector, manifest_rows, images_dir):
    """Measure the detector's hit rate within each group.

    manifest_rows : list of dicts from `provided/faces.csv`, each with at
                    least "filename" and "group"
    images_dir    : directory holding those files

    Returns a dict mapping group name to a float in [0, 1]: the fraction of
    that group's images in which at least one face was found.

    An image counts as a hit if the detector returns any face at all. Matching
    the found box against the ground-truth box is a refinement you do not need
    here, and pretending otherwise would hide the effect you are looking for
    behind a second failure mode.
    """
    counts = detection_counts_by_group(detector, manifest_rows, images_dir)
    return {group: hits / total for group, (hits, total) in counts.items()}


def detection_counts_by_group(detector, manifest_rows, images_dir):
    """The numerators and denominators behind `detection_rate_by_group`.

    Returns {group: (hits, n_images)}. A hit is an image in which the detector
    returned at least one face -- any face, anywhere. The group label is read
    from the manifest; it is never used to decide whether something is a hit.
    """
    from facedetect.faces import detect_faces

    images_dir = Path(images_dir)
    counts = {}
    for row in manifest_rows:
        group = str(row["group"])
        hits, total = counts.get(group, (0, 0))
        found = detect_faces(detector, images_dir / row["filename"])
        counts[group] = (hits + (1 if len(found) > 0 else 0), total + 1)
    return counts


def worst_group(rates):
    """Return the name of the group with the lowest detection rate.

    `rates` is the dict `detection_rate_by_group` returns. Ties break
    alphabetically, so the answer is deterministic.
    """
    if not rates:
        raise ValueError("no groups to compare")
    return min(sorted(rates), key=lambda g: rates[g])


def _main():
    """Print the audit for the memo: counts, rates, worst group, gap.

    Prints only; writes nothing. Also prints a localisation side-check that is
    NOT part of the graded metric: for each hit, whether any returned box has
    its centre inside the placed (ground-truth) tile. It exists so the report
    does not quietly treat "something was returned" as "the face was found".
    """
    import csv

    from facedetect.faces import FACE_MODEL, PROVIDED, detect_faces, load_face_detector

    rows = list(csv.DictReader(open(PROVIDED / "faces.csv", newline="")))
    images_dir = PROVIDED / "faces"
    det = load_face_detector(FACE_MODEL)
    try:
        counts, located, multi = {}, {}, {}
        for r in rows:
            g = r["group"]
            boxes = detect_faces(det, images_dir / r["filename"])
            hits, total = counts.get(g, (0, 0))
            counts[g] = (hits + (1 if boxes else 0), total + 1)
            tx1, ty1, tx2, ty2 = (float(r[k]) for k in ("x1", "y1", "x2", "y2"))
            inside = any(tx1 <= (b[0] + b[2]) / 2 <= tx2 and ty1 <= (b[1] + b[3]) / 2 <= ty2
                         for b in boxes)
            located[g] = located.get(g, 0) + (1 if inside else 0)
            multi[g] = multi.get(g, 0) + (1 if len(boxes) > 1 else 0)
    finally:
        det.close()

    rates = {g: h / n for g, (h, n) in counts.items()}
    print("hit = the detector returned at least one face for the image")
    for g in sorted(counts):
        h, n = counts[g]
        print(f"  {g:>5}: {h}/{n} = {rates[g]:.4f}   "
              f"[side-check: {located[g]}/{n} with a box centred in the placed tile; "
              f"{multi[g]} image(s) with >1 box]")
    worst = worst_group(rates)
    best = max(sorted(rates), key=lambda g: rates[g])
    print(f"worst group: {worst}")
    print(f"gap ({best} - {worst}): {100 * (rates[best] - rates[worst]):.1f} percentage points")


if __name__ == "__main__":
    _main()
